 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = [sum(row.count(c) for row in grid) for c in range(10)]
    bg = max(range(10), key=lambda c: counts[c])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] != bg:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            comps.append(comp)
    template = max(comps, key=len)
    tr0 = min(r for r, c in template)
    tr1 = max(r for r, c in template)
    tc0 = min(c for r, c in template)
    tc1 = max(c for r, c in template)
    pattern = [[grid[r][c] for c in range(tc0, tc1+1)] for r in range(tr0, tr1+1)]
    template_set = set(template)
    out = [row[:] for row in grid]
    ar, ac = (tr1-tr0)//2, (tc1-tc0)//2
    for comp in comps:
        if comp is template or len(comp) != 1:
            continue
        mr, mc = comp[0]
        top, left = mr-ar, mc-ac
        for py, row in enumerate(pattern):
            for px, value in enumerate(row):
                if value != bg:
                    y, x = top+py, left+px
                    if 0 <= y < h and 0 <= x < w:
                        out[y][x] = value
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
